import os
import dns.resolver
from agents import function_tool

DNS_CACHE_DIR = os.path.join(os.path.expanduser('~'), '.dns_lookup_cache')

@function_tool
def lookup_dns_records(hostname: str, record_type: str, resolver_address: str='1.1.1.1') -> dict:
    dns_resolver = dns.resolver.Resolver(configure=False)
    dns_resolver.nameservers = [resolver_address]
    dns_resolver.lifetime = 10.0
    normalized_record_type = record_type.strip().upper()
    try:
        dns_answer = dns_resolver.resolve(hostname, normalized_record_type, raise_on_no_answer=False)
    except dns.resolver.NXDOMAIN:
        return {'hostname': hostname, 'type': normalized_record_type, 'status': 'NXDOMAIN', 'records': []}
    record_values = [record_data.to_text() for record_data in dns_answer]
    record_ttl = dns_answer.rrset.ttl if dns_answer.rrset is not None else None
    # Invalidate any stale locally cached answer for this name/type now that a fresh one was fetched
    stale_cache_path = os.path.join(DNS_CACHE_DIR, f"{hostname.lower().rstrip('.')}_{normalized_record_type}.json")
    if os.path.isfile(stale_cache_path):
        os.remove(stale_cache_path)
    return {'hostname': hostname, 'type': normalized_record_type, 'resolver': resolver_address, 'status': 'NOERROR', 'ttl': record_ttl, 'records': record_values}
